theme.css:
/* theme: Correction Redline | A market in freefall, logged on a red-tinted trading floor where every number bleeds downward. */
/* mood: bad */
/* layout: hero=split; major-events=banner/grid-2; political-news=plain/stack; financial-news=stat/stack; tech-news=numbered/grid-2; entertainment-news=plain/stack; sports=timeline/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1013;
  --ink: #f7e8e2;
  --ink-soft: #d6c4be;
  --muted: #b08d86;
  --accent: #ff5c5c;
  --accent-ink: #1a0d08;
  --rule: #4a2a2d;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

/* header: split, with a red rule and oversized kicker */
.diary-page[data-hero="split"] .diary-hero {
  border-bottom: 4px solid var(--accent);
  background: linear-gradient(180deg, var(--paper-alt) 0%, var(--paper) 100%);
}

.diary-page .diary-kicker {
  font-size: 0.9rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent);
  border-left: 3px solid var(--accent);
  padding-left: 0.75rem;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 4.5rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-summary {
  font-size: clamp(1.15rem, 1.8vw, 1.35rem);
  line-height: 1.55;
  color: var(--ink-soft);
  border-left: 2px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-theme-note {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.9rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* body: dark red-tinted trading floor */
.diary-page .diary-body {
  padding-top: 1.5rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom-color: var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--muted);
  letter-spacing: 0.22em;
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page .diary-section {
  border-top-color: var(--rule);
  padding-block: 2.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 1.5rem;
  gap: 0.85rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--accent);
  background: var(--paper-alt);
  padding: 0.15rem 0.5rem;
  border: 1px solid var(--rule);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.9rem, 3.2vw, 2.6rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

/* cards */
.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.15;
  color: var(--ink);
}

.diary-page .diary-card-body {
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  border-radius: 0;
  font-family: var(--font-ui);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* major-events: banner */
.diary-page [data-section="major-events"] .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper);
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.05rem;
  padding: 0.7rem 1rem;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-body {
  padding: 1rem;
}

/* political-news: plain, stack — editorial flow with red h3s */
.diary-page [data-section="political-news"] .diary-stories--stack {
  gap: 1.5rem;
}

.diary-page [data-section="political-news"] .diary-card--plain + .diary-card--plain {
  padding-top: 1.25rem;
  border-top: 1px solid var(--rule);
}

.diary-page [data-section="political-news"] .diary-card--plain .diary-card-title {
  font-size: 1.6rem;
  margin-bottom: 0.4rem;
}

.diary-page [data-section="political-news"] .diary-card--plain .diary-card-body {
  font-size: 1.1rem;
}

/* financial-news: stat, stack — huge red numbers */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(3rem, 14cqi, 5rem);
  font-weight: 400;
  color: var(--accent);
  letter-spacing: -0.01em;
}

.diary-page [data-section="financial-news"] .diary-stories--stack {
  max-width: 100%;
}

/* tech-news: numbered, grid-2 */
.diary-page [data-section="tech-news"] .diary-card--numbered .diary-card-inner {
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1rem;
  row-gap: 0.5rem;
  background: var(--paper);
  border: 1px solid var(--rule);
  padding: 1.25rem;
}

.diary-page [data-section="tech-news"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.6rem;
  font-weight: 400;
  line-height: 0.9;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page [data-section="tech-news"] .diary-card-title {
  font-size: 1.25rem;
}

/* entertainment-news: plain */
.diary-page [data-section="entertainment-news"] .diary-stories--stack {
  gap: 1.25rem;
}

.diary-page [data-section="entertainment-news"] .diary-card--plain + .diary-card--plain {
  padding-top: 1.25rem;
  border-top: 1px solid var(--rule);
}

/* sports: timeline, masonry */
.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner {
  padding-left: 1.6rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::before {
  left: 0.25rem;
  background: var(--rule);
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::after {
  left: 0;
  width: 0.6rem;
  height: 0.6rem;
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--paper);
}

.diary-page [data-section="sports"] .diary-card-title {
  font-size: 1.2rem;
}

.diary-page [data-section="sports"] .diary-card-body {
  font-size: 1rem;
}

/* music-releases: plain, unboxed players */
.diary-page [data-section="music-releases"] .diary-stories--stack {
  gap: 1.5rem;
}

/* stock-analysis: stat, grid-3 */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 1rem;
  background: var(--paper-alt);
  border-left: 1px solid var(--rule);
  border-right: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-size: clamp(2.2rem, 10cqi, 3rem);
  color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1.15rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 1rem;
}

/* outlook: tile, grid-2 */
.diary-page [data-section="outlook"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.25rem;
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.25rem;
  color: var(--accent);
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1rem;
}

/* prose adjustments */
.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
  font-size: 1.2rem;
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
}

/* drop cap */
.diary-page .diary-section:first-child .diary-card--banner:first-child .diary-prose > p:first-of-type::first-letter {
  float: left;
  margin: 0.04em 0.08em 0 0;
  font-family: var(--font-display);
  font-size: 3.2em;
  font-weight: 400;
  line-height: 0.82;
  color: var(--accent);
}

/* markets */
.diary-page .diary-markets-label {
  color: var(--muted);
  letter-spacing: 0.18em;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* footer */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* toc vertical rail */
@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}
